import "pe"

rule MAL_CredStealer_Confirmed_Sample_Set
{
    meta:
        description   = "Detects confirmed credential-stealer samples using analyst-extracted indicators"
        author        = "SOC Detection Engineering"
        date          = "2026-07-31"
        scope         = "Confirmed sample set only"
        attribution   = "No family-wide attribution; indicators may occur in unrelated software"
        sample_sha256 = "REPLACE_WITH_CONFIRMED_SAMPLE_SHA256"
        confidence    = "high"

    strings:
        // Windows DPAPI function commonly used to decrypt stored credentials.
        $api_dpapi  = "CryptUnprotectData" ascii wide fullword

        // SQLite function potentially used to access browser credential databases.
        $api_sqlite = "sqlite3_open" ascii wide fullword

    condition:
        // Require a valid PE containing both extracted strings.
        pe.is_pe and
        all of ($api_*) and

        // Require both section names observed in the confirmed sample set.
        for any i in (0 .. pe.number_of_sections - 1): (
            pe.sections[i].name == ".text"
        ) and
        for any i in (0 .. pe.number_of_sections - 1): (
            pe.sections[i].name == ".rdata"
        )
}
```

This intentionally uses a sample-set-oriented rule name and metadata rather than claiming comprehensive RedLine family coverage. Replace the SHA-256 placeholder and validate against benign software containing both APIs before deployment.

