    if not value:
        return 0.0
    counts = Counter(value.lower())
    length = len(value)
    return -sum((count / length) * math.log2(count / length) for count in counts.values())


def normalize_qname(qname: bytes | str) -> str:
    if isinstance(qname, bytes):
        return qname.decode("ascii", errors="replace").rstrip(".").lower()
    return str(qname).rstrip(".").lower()


def base_domain(qname: str, labels: int) -> str:
    """Approximate a registrable domain using its last N labels."""
    parts = [part for part in qname.split(".") if part]
    return ".".join(parts[-labels:]) if parts else qname


def dns_questions(packet: object) -> Iterable[str]:
    """Yield all DNS question names from a Scapy packet."""
    if not packet.haslayer(DNS):
        return

    dns = packet[DNS]
    if dns.qr != 0 or not dns.qd:
        return

    questions = dns.qd
    if not isinstance(questions, DNSQR):
        for question in questions:
            if isinstance(question, DNSQR):
                yield normalize_qname(question.qname)
        return

    question = questions
    seen = 0
    while isinstance(question, DNSQR) and seen < int(dns.qdcount or 1):
        yield normalize_qname(question.qname)
        seen += 1
        question = question.payload


def source_address(packet: object) -> str:
    if packet.haslayer(IP):
        return str(packet[IP].src)
    if packet.haslayer(IPv6):
        return str(packet[IPv6].src)
    return "unknown"


def analyze_capture(
    pcap_path: str,
    long_label_threshold: int,
    entropy_threshold: float,
    entropy_min_length: int,
    volume_threshold: int,
    domain_labels: int,
) -> tuple[list[Finding], Counter[str], int]:
    findings: list[Finding] = []
    domain_counts: Counter[str] = Counter()
    query_count = 0

    with PcapReader(pcap_path) as packets:
        for packet in packets:
            timestamp = float(packet.time)
            source = source_address(packet)

            for query in dns_questions(packet):
                query_count += 1
                domain_counts[base_domain(query, domain_labels)] += 1

                # The final labels usually identify the destination domain, so
                # inspect only labels preceding that domain for encoded payloads.
                labels = [part for part in query.split(".") if part]
                subdomain_labels = labels[:-domain_labels] if len(labels) > domain_labels else []

                for label in subdomain_labels:
                    if len(label) >= long_label_threshold:
                        findings.append(
                            Finding(
                                timestamp,
                                source,
                                query,
                                "long_label",
                                f"label length {len(label)} (threshold {long_label_threshold})",
                            )
                        )

                    entropy = shannon_entropy(label)
                    if len(label) >= entropy_min_length and entropy >= entropy_threshold:
                        findings.append(
                            Finding(
                                timestamp,
                                source,
                                query,
                                "high_entropy",
                                f"entropy {entropy:.2f} bits/char (threshold {entropy_threshold:.2f})",
                            )
                        )

    for domain, count in domain_counts.items():
        if count >= volume_threshold:
            findings.append(
                Finding(
                    0.0,
                    "multiple/unknown",
                    domain,
                    "high_volume",
                    f"{count} queries (threshold {volume_threshold})",
                )
            )

    return findings, domain_counts, query_count


def format_timestamp(timestamp: float) -> str:
    if timestamp == 0.0:
        return "capture-summary"
    return datetime.fromtimestamp(timestamp, tz=timezone.utc).isoformat()


def positive_int(value: str) -> int:
    parsed = int(value)
    if parsed <= 0:
        raise argparse.ArgumentTypeError("must be greater than zero")
    return parsed


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Analyze a PCAP for common DNS-tunneling indicators."
    )
    parser.add_argument("pcap", help="PCAP or PCAPNG file to analyze")
    parser.add_argument(
        "--long-label-threshold",
        type=positive_int,
        default=40,
        help="flag subdomain labels at least this long (default: 40)",
    )
    parser.add_argument(
        "--entropy-threshold",
        type=float,
        default=4.0,
        help="flag entropy at or above this many bits/character (default: 4.0)",
    )
    parser.add_argument(
        "--entropy-min-length",
        type=positive_int,
        default=12,
        help="minimum label length for entropy checks (default: 12)",
    )
    parser.add_argument(
        "--volume-threshold",
        type=positive_int,
        default=100,
        help="flag domains with at least this many queries (default: 100)",
    )
    parser.add_argument(
        "--domain-labels",
        type=positive_int,
        default=2,
        help="number of trailing labels treated as the base domain (default: 2)",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    try:
        findings, domain_counts, query_count = analyze_capture(
            args.pcap,
            args.long_label_threshold,
            args.entropy_threshold,
            args.entropy_min_length,
            args.volume_threshold,
            args.domain_labels,
        )
    except (OSError, ValueError, Scapy_Exception) as exc:
        print(f"error: could not analyze {args.pcap!r}: {exc}", file=sys.stderr)
        return 2

    print(f"Analyzed {query_count} DNS queries across {len(domain_counts)} base domains.")
    if not findings:
        print("No indicators exceeded the configured thresholds.")
        return 0

    print(f"Flagged {len(findings)} indicator(s):")
    for finding in sorted(findings, key=lambda item: (item.timestamp, item.query, item.indicator)):
        print(
            f"[{format_timestamp(finding.timestamp)}] {finding.indicator}: "
            f"source={finding.source} query={finding.query} detail={finding.detail}"
        )
    return 1


if __name__ == "__main__":
    raise SystemExit(main())

