	string "could not connect to pipe";
	string "Maximum links reached. Disconnect one";
	string "%d	%d	%d.%d	%s	%s	%s	%d	%d";
	string "Could not bind to %d";
	string "IEX (New-Object Net.Webclient).DownloadString('http://127.0.0.1:%u/')";
	string "%%IMPORT%%";
	string "Command length (%d) too long";
	string "IEX (New-Object Net.Webclient).DownloadString('http://127.0.0.1:%u/'); %s";
	string "powershell -nop -exec bypass -EncodedCommand \"%s\"";
	string "?%s=%s";
	string "%s&%s=%s";
	string "%s%s: %s";
	string "%s&%s";
	string "%s%s";
	string "Could not kill %d: %d";
	string "%s	%d	%d";
	string "%s	%d	%d	%s	%s	%d";
	string "%s\\*";
	string "sha256";
	string "abcdefghijklmnop";
	string "sprng";
	string "could not create pipe: %d";
	string "I'm already in SMB mode";
	string "%s (admin)";
	string "Could not open process: %d (%u)";
	string "Failed to impersonate token from %d (%u)";
	string "Failed to duplicate primary token for %d (%u)";
	string "Failed to impersonate logged on user %d (%u)";
	string "Could not create token: %d";
	string "HTTP/1.1 200 OK";
	string "Content-Type: application/octet-stream";
	string "Content-Length: %d";
	string "Microsoft Base Cryptographic Provider v1.0";
}

# define indicators for an HTTP GET
http-get {
	# Beacon will randomly choose from this pool of URIs
	set uri "/ca /dpixel /__utm.gif /pixel.gif /g.pixel /dot.gif /updates.rss /fwlink /cm /cx /pixel /match /visit.js /load /push /ptj /j.ad /ga.js /en_US/all.js /activity /IE9CompatViewList.xml";

	client {
		# base64 encode session metadata and store it in the Cookie header.
		metadata {
			base64;
			header "Cookie";
		}
	}

	server {
		# server should send output with no changes
		header "Content-Type" "application/octet-stream";

		output {
			print;
		}
	}
}

# define indicators for an HTTP POST
http-post {
	# Same as above, Beacon will randomly choose from this pool of URIs [if multiple URIs are provided]
	set uri "/submit.php";

	client {
		header "Content-Type" "application/octet-stream";

		# transmit our session identifier as /submit.php?id=[identifier]
		id {
			parameter "id";
		}

		# post our output with no real changes
		output {
			print;
		}
	}

	# The server's response to our HTTP POST
	server {
		header "Content-Type" "text/html";

		# this will just print an empty string, meh...
		output {
			print;
		}
	}
}

# define indicators/attributes for a DNS Beacon
dns-beacon {
    # maximum number of bytes to send in a DNS A record request
    set maxdns    "255";

    set beacon "";
    set get_A "cdn.";
    set get_AAAA "www6.";
    set get_TXT "api.";
    set put_metadata "www.";
    set put_output "post.";
}

parts.text:
The default profile is most reliably identified by outbound `POST /submit.php?id=<numeric beacon ID>` requests carrying binary output:

```suricata
alert http $HOME_NET any -> $EXTERNAL_NET $HTTP_PORTS (
    msg:"MALWARE-C2 possible Cobalt Strike default Beacon HTTP POST";
    flow:established,to_server;
    http.method; content:"POST";
    http.uri; content:"/submit.php?id="; startswith; fast_pattern;
    pcre:"/^\/submit\.php\?id=[0-9]+$/";
    http.request_header; content:"application/octet-stream"; nocase;
    classtype:trojan-activity;
    sid:1000001;
    rev:1;
)
```

An additional, lower-confidence rule detects default check-ins using one of the stock URI paths and base64 metadata in the `Cookie` header:

```suricata
alert http $HOME_NET any -> $EXTERNAL_NET $HTTP_PORTS (
    msg:"MALWARE-C2 possible Cobalt Strike default Beacon HTTP GET";
    flow:established,to_server;
    http.method; content:"GET";
    http.uri;
    pcre:"/^\/(?:ca|dpixel|__utm\.gif|pixel\.gif|g\.pixel|dot\.gif|updates\.rss|fwlink|cm|cx|pixel|match|visit\.js|load|push|ptj|j\.ad|ga\.js|en_US\/all\.js|activity|IE9CompatViewList\.xml)$/";
    http.cookie;
    pcre:"/^[A-Za-z0-9+\/]{160,220}={0,2}$/";
    classtype:trojan-activity;
    sid:1000002;
    rev:1;
)
```

**Brittleness**
- **VERIFIED, high confidence:** `/submit.php`, the `id` parameter, stock GET URI pool, HTTP methods, `Cookie` placement, base64 transform, and `application/octet-stream` are all controlled by the Malleable C2 profile. An operator can change each without modifying Beacon itself.
- The cookie regex assumes the default base64-encoded metadata shape. Operators can use `mask`, `netbios`, `base64url`, prepend/append data, or move metadata into a URI parameter, another header, or the path.
- User-Agent signatures are especially brittle: the default already varies among Internet Explorer-style values, and profiles can override it.
- Sleep interval and periodicity are weak alone. Operators can change `sleeptime`, add jitter, or introduce traffic shaping.
- TLS hides all these HTTP elements unless Suricata receives decrypted traffic.
- `$EXTERNAL_NET` will miss callbacks to internal red-team redirectors if those addresses are part of `$HOME_NET`.

Treat the POST rule as relatively high-signal and the GET rule as a hunting alert because several stock paths are common in legitimate web traffic. Validate both against your Suricata version with `suricata -T -c /path/to/suricata.yaml -S /path/to/rules`.

text:
A representative Suricata rule for Cobalt Strike’s legacy default HTTP GET profile is:

```suricata
alert http $HOME_NET any -> $EXTERNAL_NET any (
    msg:"MALWARE Cobalt Strike default HTTP beacon GET";
    flow:established,to_server;
    http.method;
    content:"GET";
    http.uri;
    content:"/activity";
    startswith;
    http.cookie;
    pcre:"/(?:^|;\x20*)user=[A-Za-z0-9+\/]{16,}={0,2}(?:;|$)/";
    classtype:trojan-activity;
    sid:1000001;
    rev:1;
)
```

A companion rule can cover the default POST channel:

```suricata
alert http $HOME_NET any -> $EXTERNAL_NET any (
    msg:"MALWARE Cobalt Strike default HTTP beacon POST";
    flow:established,to_server;
    http.method;
    content:"POST";
    http.uri;
    content:"/submit.php";
    startswith;
    http.request_body;
    content:!"";
    classtype:trojan-activity;
    sid:1000002;
    rev:1;
)
```

These should be treated as hunting signatures rather than definitive attribution. Test them against your Suricata version and local traffic before deploying in blocking mode.

**Brittle elements**

- `/activity` and `/submit.php`: trivially replaced in a Malleable C2 profile.
- `Cookie: user=`: the metadata can move to another cookie, header, URI parameter, or request body.
- Base64 shape: operators can apply different encodings and transformations.
- HTTP method: GET and POST behavior can be changed.
- Headers and User-Agent: fully configurable and often deliberately made browser-like.
- Request size or timing: affected by sleep, jitter, tasking, and padding.
- Destination IP, domain, and port: infrastructure is easily rotated.
- HTTP visibility: HTTPS hides these fields unless traffic is decrypted before Suricata inspection.

For stronger coverage, combine these alerts with TLS certificate/JA3 or JA4 telemetry, rare-domain analysis, periodic connection patterns, endpoint process telemetry, and detections for known Beacon named pipes or injection behavior. Avoid relying on the default User-Agent alone because it produces substantial false positives and is especially easy to customize.

